// Onitama (Declarative). Two players (Red = seat 0, Blue = seat 1) each lead
// one master and four students on a 5x5 board (cells 0-24, row-major from
// Blue's back rank at the top to Red's back rank at the bottom). Pieces are
// encoded 0 = Red student, 1 = Red master, 2 = Blue student, 3 = Blue master,
// -1 = empty. Red's temple is cell 22 (its own back-centre), Blue's temple is
// cell 2; a master wins by reaching the OPPONENT's temple (Red -> 2,
// Blue -> 22) or by capturing the opponent's master.
//
// CARD OFFSET TABLE (all 16 real base-game cards). Offsets are
// [forward, right] from the CARD HOLDER's perspective: forward is toward the
// opponent, right is the holder's own right. Board transform: Red (seat 0,
// facing up-board) dr = -forward, dc = +right; Blue (seat 1, facing
// down-board) dr = +forward, dc = -right. Verified against the printed cards:
//   Tiger    (blue stamp): [2,0] [-1,0]
//   Crab     (blue stamp): [1,0] [0,-2] [0,2]
//   Monkey   (blue stamp): [1,-1] [1,1] [-1,-1] [-1,1]
//   Crane    (blue stamp): [1,0] [-1,-1] [-1,1]
//   Dragon   (red stamp):  [1,-2] [1,2] [-1,-1] [-1,1]
//   Elephant (red stamp):  [1,-1] [1,1] [0,-1] [0,1]
//   Mantis   (red stamp):  [1,-1] [1,1] [-1,0]
//   Boar     (red stamp):  [1,0] [0,-1] [0,1]
//   Frog     (red stamp):  [0,-2] [1,-1] [-1,1]
//   Goose    (blue stamp): [1,-1] [0,-1] [0,1] [-1,1]
//   Rooster  (red stamp):  [1,1] [0,1] [0,-1] [-1,-1]
//   Rabbit   (blue stamp): [0,2] [1,1] [-1,-1]
//   Ox       (blue stamp): [1,0] [0,1] [-1,0]
//   Horse    (red stamp):  [1,0] [0,-1] [-1,0]
//   Eel      (blue stamp): [1,-1] [-1,-1] [0,1]
//   Cobra    (red stamp):  [1,1] [-1,1] [0,-1]
// Eight cards carry a red stamp and eight a blue stamp, as in the real game.
// The player whose colour matches the NEUTRAL card's stamp moves first.
const CARDS = {
  tiger: { name: 'Tiger', stamp: 'blue', off: [[2, 0], [-1, 0]] },
  crab: { name: 'Crab', stamp: 'blue', off: [[1, 0], [0, -2], [0, 2]] },
  monkey: { name: 'Monkey', stamp: 'blue', off: [[1, -1], [1, 1], [-1, -1], [-1, 1]] },
  crane: { name: 'Crane', stamp: 'blue', off: [[1, 0], [-1, -1], [-1, 1]] },
  dragon: { name: 'Dragon', stamp: 'red', off: [[1, -2], [1, 2], [-1, -1], [-1, 1]] },
  elephant: { name: 'Elephant', stamp: 'red', off: [[1, -1], [1, 1], [0, -1], [0, 1]] },
  mantis: { name: 'Mantis', stamp: 'red', off: [[1, -1], [1, 1], [-1, 0]] },
  boar: { name: 'Boar', stamp: 'red', off: [[1, 0], [0, -1], [0, 1]] },
  frog: { name: 'Frog', stamp: 'red', off: [[0, -2], [1, -1], [-1, 1]] },
  goose: { name: 'Goose', stamp: 'blue', off: [[1, -1], [0, -1], [0, 1], [-1, 1]] },
  rooster: { name: 'Rooster', stamp: 'red', off: [[1, 1], [0, 1], [0, -1], [-1, -1]] },
  rabbit: { name: 'Rabbit', stamp: 'blue', off: [[0, 2], [1, 1], [-1, -1]] },
  ox: { name: 'Ox', stamp: 'blue', off: [[1, 0], [0, 1], [-1, 0]] },
  horse: { name: 'Horse', stamp: 'red', off: [[1, 0], [0, -1], [-1, 0]] },
  eel: { name: 'Eel', stamp: 'blue', off: [[1, -1], [-1, -1], [0, 1]] },
  cobra: { name: 'Cobra', stamp: 'red', off: [[1, 1], [-1, 1], [0, -1]] }
};
const DECK = ['tiger', 'crab', 'monkey', 'crane', 'dragon', 'elephant', 'mantis', 'boar',
  'frog', 'goose', 'rooster', 'rabbit', 'ox', 'horse', 'eel', 'cobra'];
const MAX_MOVES = 500; // safety valve: 500 moves without a win is a draw, pot split

function ownerOf(piece) { return piece < 0 ? -1 : (piece >= 2 ? 1 : 0); }
// Stable piece identities. state.pieces maps a permanent pawn id to its
// current cell: Blue students b_s0..b_s3 and master b_m start on cells
// 0,1,2,3,4 and Red students r_s0..r_s3 and master r_m on cells
// 20,21,22,23,24 (students numbered in cell order over their home rank).
// An id never changes hands: a move updates only the mover's cell and a
// capture deletes only the captured pawn's entry. The board array alone
// cannot carry identity (two students of one colour share one code), so
// the presentation renders pawn ids from this map. piecesFromBoard
// rebuilds the map in cell order for a legacy state that predates it.
function piecesFromBoard(board) {
  const pieces = {}; let rs = 0, bs = 0;
  for (let cell = 0; cell < 25; cell++) {
    const v = board[cell];
    if (v === 0) pieces['r_s' + (rs++)] = cell;
    else if (v === 1) pieces.r_m = cell;
    else if (v === 2) pieces['b_s' + (bs++)] = cell;
    else if (v === 3) pieces.b_m = cell;
  }
  return pieces;
}
function pieceIdAt(pieces, cell) {
  for (const id of Object.keys(pieces)) if (pieces[id] === cell) return id;
  return null;
}
function cellPos(cell) { return { board: 'main', position: { cell: String(cell) } }; }
function isMaster(piece) { return piece === 1 || piece === 3; }
function copyState(s) { return JSON.parse(JSON.stringify(s)); }
function seatOf(ctx, playerId) {
  for (let i = 0; i < ctx.players.length; i++) if (ctx.players[i].id === playerId) return i;
  return -1;
}
function destFor(seat, from, off) {
  const r = Math.floor(from / 5), c = from % 5;
  const dr = seat === 0 ? -off[0] : off[0];
  const dc = seat === 0 ? off[1] : -off[1];
  const nr = r + dr, nc = c + dc;
  if (nr < 0 || nr > 4 || nc < 0 || nc > 4) return -1;
  return nr * 5 + nc;
}
// Every real move (not passes) available to `seat` in state s.
function realMoves(s, seat) {
  const out = [];
  const hand = s.hands[seat] || [];
  for (const card of hand) {
    const def = CARDS[card];
    if (!def) continue;
    for (let from = 0; from < 25; from++) {
      if (ownerOf(s.board[from]) !== seat) continue;
      for (const off of def.off) {
        const to = destFor(seat, from, off);
        if (to < 0) continue;
        if (ownerOf(s.board[to]) === seat) continue;
        out.push({ type: 'move', from: from, to: to, card: card });
      }
    }
  }
  return out;
}
// Legal moves for the side to move: real moves, or a pass of either card
// when no real move exists (the real Onitama pass rule).
function legalMoves(s) {
  const moves = realMoves(s, s.turn);
  if (moves.length) return moves;
  return (s.hands[s.turn] || []).map(card => ({ type: 'pass', card: card }));
}
function payoutsFor(s, ctx) {
  const pot = ctx.pot || 0;
  if (pot <= 0) return {};
  const humans = ctx.players.filter(p => p.kind === 'human' && p.active !== false);
  if (!humans.length) return {};
  const out = {};
  if (!s.draw && s.winner >= 0) {
    const w = ctx.players[s.winner];
    if (w && w.kind === 'human' && w.active !== false) {
      for (const p of humans) out[p.id] = 0;
      out[w.id] = pot;
      return out;
    }
  }
  const each = Math.floor(pot / humans.length);
  let rem = pot - each * humans.length;
  for (const p of humans) { out[p.id] = each + (rem > 0 ? 1 : 0); if (rem > 0) rem--; }
  return out;
}
function swapCard(s, seat, card) {
  const idx = s.hands[seat].indexOf(card);
  const old = s.hands[seat][idx];
  s.hands[seat][idx] = s.neutral;
  s.neutral = old;
}

const game = {
  newMatch(ctx) {
    const deck = DECK.slice();
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(ctx.random() * (i + 1));
      const t = deck[i]; deck[i] = deck[j]; deck[j] = t;
    }
    const board = Array(25).fill(-1);
    board[0] = 2; board[1] = 2; board[2] = 3; board[3] = 2; board[4] = 2;
    board[20] = 0; board[21] = 0; board[22] = 1; board[23] = 0; board[24] = 0;
    const neutral = deck[4];
    const start = CARDS[neutral].stamp === 'red' ? 0 : 1;
    const s = {
      board: board, pieces: piecesFromBoard(board),
      hands: [[deck[0], deck[1]], [deck[2], deck[3]]],
      neutral: neutral,
      turn: start, winner: -1, draw: false, moves: 0, over: false,
      last_move: null
    };
    return { state: s, turn: [ctx.players[start].id] };
  },
  applyMove(state, playerId, move, ctx) {
    if (!state || state.over) throw new InvalidMove('game over');
    const seat = seatOf(ctx, playerId);
    if (seat < 0 || seat !== state.turn) throw new InvalidMove('not your turn');
    if (!move || typeof move !== 'object' || Array.isArray(move)) throw new InvalidMove('bad move');
    const keys = Object.keys(move).sort().join(',');
    if (typeof move.card !== 'string' || !CARDS[move.card]) throw new InvalidMove('unknown card');
    if (state.hands[seat].indexOf(move.card) < 0) throw new InvalidMove('card not held');
    const s = copyState(state);
    if (!s.pieces) s.pieces = piecesFromBoard(s.board);
    if (move.type === 'pass') {
      if (keys !== 'card,type') throw new InvalidMove('bad move');
      if (realMoves(s, seat).length) throw new InvalidMove('a move is available');
      swapCard(s, seat, move.card);
      s.last_move = { kind: 'pass', piece_id: null, from: null, to: null, captured_piece_id: null };
    } else if (move.type === 'move') {
      if (keys !== 'card,from,to,type') throw new InvalidMove('bad move');
      const from = move.from, to = move.to;
      if (!Number.isInteger(from) || !Number.isInteger(to) || from < 0 || from > 24 || to < 0 || to > 24)
        throw new InvalidMove('off board');
      const piece = s.board[from];
      if (ownerOf(piece) !== seat) throw new InvalidMove('not your piece');
      if (ownerOf(s.board[to]) === seat) throw new InvalidMove('your own piece is there');
      let ok = false;
      for (const off of CARDS[move.card].off) if (destFor(seat, from, off) === to) { ok = true; break; }
      if (!ok) throw new InvalidMove('card does not move like that');
      const captured = s.board[to];
      const moverId = pieceIdAt(s.pieces, from);
      const capturedId = captured >= 0 ? pieceIdAt(s.pieces, to) : null;
      s.board[to] = piece;
      s.board[from] = -1;
      if (capturedId) delete s.pieces[capturedId];
      if (moverId) s.pieces[moverId] = to;
      s.last_move = { kind: 'move', piece_id: moverId, from: cellPos(from), to: cellPos(to), captured_piece_id: capturedId };
      swapCard(s, seat, move.card);
      if (isMaster(captured) && ownerOf(captured) === 1 - seat) { s.winner = seat; s.over = true; }
      else if (isMaster(piece) && to === (seat === 0 ? 2 : 22)) { s.winner = seat; s.over = true; }
    } else {
      throw new InvalidMove('bad move');
    }
    s.moves++;
    if (!s.over && s.moves >= MAX_MOVES) { s.draw = true; s.over = true; s.winner = -1; }
    if (s.over) return { state: s, turn: null, payouts: payoutsFor(s, ctx) };
    s.turn = 1 - seat;
    return { state: s, turn: [ctx.players[s.turn].id] };
  },
  viewFor(state, playerId, ctx) {
    const s = copyState(state);
    const seat = seatOf(ctx, playerId);
    const view = {
      board: s.board, pieces: s.pieces || piecesFromBoard(s.board),
      hands: s.hands, neutral: s.neutral, turn: s.turn,
      winner: s.winner, draw: s.draw, moves: s.moves, over: s.over,
      last_move: s.last_move === undefined ? null : s.last_move,
      me: seat, legal: []
    };
    if (!s.over && seat === s.turn) view.legal = legalMoves(s);
    return view;
  },
  randomMove(state, playerId, ctx) {
    const options = legalMoves(state);
    return options[Math.floor(ctx.random() * options.length)];
  },
  computerMove(state, playerId, ctx) {
    const seat = state.turn;
    const options = legalMoves(state);
    let best = options[0], bestScore = -1e9;
    for (const m of options) {
      let score = ctx.random() * 1.5;
      if (m.type === 'pass') { score -= 5; }
      else {
        const piece = state.board[m.from];
        const target = state.board[m.to];
        if (isMaster(target) && ownerOf(target) === 1 - seat) score += 1000;
        else if (isMaster(piece) && m.to === (seat === 0 ? 2 : 22)) score += 1000;
        else if (target >= 0) score += 100; // capture a student
        const progress = seat === 0 ? (Math.floor(m.from / 5) - Math.floor(m.to / 5))
                                    : (Math.floor(m.to / 5) - Math.floor(m.from / 5));
        score += isMaster(piece) ? progress * 8 : progress * 2;
        if (isMaster(piece)) score += 4;
      }
      if (score > bestScore) { bestScore = score; best = m; }
    }
    return best;
  }
};

