// Onitama presentation. Pure reducer: scene + staged local selection.
// Interaction (acting viewer only): tap one of your card panels (a target
// over the panel), then tap a highlighted piece (origin target), then tap a
// highlighted destination target. The destination targets are only emitted
// for the staged (card, piece) pair, so every legal (from, to, card) move is
// reachable and unambiguous even when both cards reach the same square.
// When no legal move exists, a Pass button per held card emits the pass.
// Spectators, replay and finished games get no targets or controls.
const SOURCE_STRINGS = {"title": "Onitama", "red": "Red", "blue": "Blue", "turn": "{name} to move", "your_turn": "Your turn \u00b7 {name}", "finished": "Game over", "winner": "Winner: {name}", "draw": "Draw", "temple": "TEMPLE", "neutral": "Neutral card", "red_cards": "Red cards", "blue_cards": "Blue cards", "hint_card": "Tap one of your cards to choose it.", "hint_piece": "Tap a highlighted piece to move.", "hint_dest": "Tap a highlighted destination.", "hint_pass": "No legal move \u2014 pass a card instead.", "pass_card": "Pass {card}", "use_card": "Use the {card} card", "move_to": "Move to row {r}, column {c}", "select_piece": "Select piece at row {r}, column {c}", "master": "Master", "student": "Student", "server_game_over": "game over", "server_not_your_turn": "not your turn", "server_bad_move": "bad move", "server_unknown_card": "unknown card", "server_card_not_held": "card not held", "server_move_available": "a move is available", "server_off_board": "off board", "server_not_your_piece": "not your piece", "server_own_piece": "your own piece is there", "server_card_move": "card does not move like that"};
const CARD_INFO = {"tiger": {"name": "Tiger", "stamp": "blue", "off": [[2, 0], [-1, 0]]}, "crab": {"name": "Crab", "stamp": "blue", "off": [[1, 0], [0, -2], [0, 2]]}, "monkey": {"name": "Monkey", "stamp": "blue", "off": [[1, -1], [1, 1], [-1, -1], [-1, 1]]}, "crane": {"name": "Crane", "stamp": "blue", "off": [[1, 0], [-1, -1], [-1, 1]]}, "dragon": {"name": "Dragon", "stamp": "red", "off": [[1, -2], [1, 2], [-1, -1], [-1, 1]]}, "elephant": {"name": "Elephant", "stamp": "red", "off": [[1, -1], [1, 1], [0, -1], [0, 1]]}, "mantis": {"name": "Mantis", "stamp": "red", "off": [[1, -1], [1, 1], [-1, 0]]}, "boar": {"name": "Boar", "stamp": "red", "off": [[1, 0], [0, -1], [0, 1]]}, "frog": {"name": "Frog", "stamp": "red", "off": [[0, -2], [1, -1], [-1, 1]]}, "goose": {"name": "Goose", "stamp": "blue", "off": [[1, -1], [0, -1], [0, 1], [-1, 1]]}, "rooster": {"name": "Rooster", "stamp": "red", "off": [[1, 1], [0, 1], [0, -1], [-1, -1]]}, "rabbit": {"name": "Rabbit", "stamp": "blue", "off": [[0, 2], [1, 1], [-1, -1]]}, "ox": {"name": "Ox", "stamp": "blue", "off": [[1, 0], [0, 1], [-1, 0]]}, "horse": {"name": "Horse", "stamp": "red", "off": [[1, 0], [0, -1], [-1, 0]]}, "eel": {"name": "Eel", "stamp": "blue", "off": [[1, -1], [-1, -1], [0, 1]]}, "cobra": {"name": "Cobra", "stamp": "red", "off": [[1, 1], [-1, 1], [0, -1]]}};
const gameUI = {
  reduce(message, localState) {
    const m = message.type === 'ui_event' ? message.state_changed : message;
    const s = m.view || m.state || {};
    const strings = Object.assign({}, SOURCE_STRINGS, m.strings || {});
    const t = (key, args) => String(strings[key] || SOURCE_STRINGS[key] || key).replace(/\{(\w+)\}/g,
      (_, k) => String((args || {})[k] === undefined ? '' : (args || {})[k]));
    const active = m.status === 'ongoing' && !m.replay &&
      m.acting_for_player_index !== null && m.acting_for_player_index !== undefined;
    const mySeat = (m.my_player_index === 0 || m.my_player_index === 1) ? m.my_player_index : -1;
    const legal = active ? (s.legal || []) : [];
    const moves = legal.filter(x => x.type === 'move');
    const passes = legal.filter(x => x.type === 'pass');
    const playerName = i => {
      const p = (m.players || [])[i];
      return p && p.name ? p.name : t(i === 0 ? 'red' : 'blue');
    };
    // --- staged selection, retained only for the same move and viewer ---
    let selCard = null, selFrom = null;
    if (localState && localState.mc === m.move_count && localState.vw === mySeat) {
      selCard = localState.card || null;
      selFrom = typeof localState.from === 'number' ? localState.from : null;
    }
    if (!moves.some(x => x.card === selCard)) { selCard = null; selFrom = null; }
    if (selCard !== null && !moves.some(x => x.card === selCard && x.from === selFrom)) selFrom = null;
    let makeMove = null;
    if (message.type === 'ui_event' && active && message.event && message.event.type === 'tap') {
      const id = String(message.event.id || '');
      if (id.indexOf('pass_') === 0) {
        const cid = id.slice(5);
        if (passes.some(x => x.card === cid)) makeMove = { type: 'pass', card: cid };
      } else if (id.indexOf('card_') === 0) {
        const cid = id.slice(5);
        if (moves.some(x => x.card === cid)) { selCard = cid; selFrom = null; }
      } else if (id.indexOf('from_') === 0) {
        const cell = parseInt(id.slice(5), 10);
        if (selCard && moves.some(x => x.card === selCard && x.from === cell)) selFrom = cell;
      } else if (id.indexOf('to_') === 0) {
        const cell = parseInt(id.slice(3), 10);
        const found = moves.find(x => x.card === selCard && x.from === selFrom && x.to === cell);
        if (found) makeMove = { type: 'move', from: found.from, to: found.to, card: found.card };
      }
    }
    // --- scene ---
    const pieces = [], targets = [], controls = [], labels = [];
    labels.push({ id: 'title', text: t('title'), x: 24, y: 14, font_size: 25 });
    const over = s.over || m.status === 'over';
    if (over) {
      labels.push({ id: 'status', text: t('finished'), x: 24, y: 46, font_size: 17 });
      if (s.draw) labels.push({ id: 'winner', text: t('draw'), x: 24, y: 70, font_size: 15 });
      else if (s.winner === 0 || s.winner === 1)
        labels.push({ id: 'winner', text: t('winner', { name: playerName(s.winner) }), x: 24, y: 70, font_size: 15 });
    } else {
      const nm = playerName(s.turn);
      labels.push({ id: 'status', text: active && mySeat === s.turn ? t('your_turn', { name: nm }) : t('turn', { name: nm }), x: 24, y: 46, font_size: 17 });
      if (active && passes.length)
        labels.push({ id: 'hint', text: t('hint_pass'), x: 24, y: 70, font_size: 14 });
      else if (active && moves.length)
        labels.push({ id: 'hint', text: t(!selCard ? 'hint_card' : selFrom === null ? 'hint_piece' : 'hint_dest'), x: 24, y: 70, font_size: 14 });
    }
    labels.push({ id: 'temple_top', text: t('temple'), x: 256, y: 95, font_size: 10 });
    labels.push({ id: 'temple_bottom', text: t('temple'), x: 256, y: 383, font_size: 10 });
    // Board pieces carry STABLE ids from view.pieces (permanent pawn id ->
    // current cell), never the cell itself: a pawn keeps its id as it
    // moves, so the host can animate it, and a captured pawn simply
    // disappears. A legacy view without a pieces map derives one in cell
    // order from the board codes, matching the server's rebuild.
    const pieceMap = (s.pieces && typeof s.pieces === 'object') ? s.pieces : (() => {
      const map = {}; let rs = 0, bs = 0;
      (s.board || []).forEach((v, cell) => {
        if (v === 0) map['r_s' + (rs++)] = cell;
        else if (v === 1) map.r_m = cell;
        else if (v === 2) map['b_s' + (bs++)] = cell;
        else if (v === 3) map.b_m = cell;
      });
      return map;
    })();
    for (const pid of Object.keys(pieceMap)) {
      const cell = pieceMap[pid];
      if (typeof cell !== 'number' || cell < 0 || cell > 24) continue;
      const v = (s.board || [])[cell];
      const seat = typeof v === 'number' && v >= 0 ? (v >= 2 ? 1 : 0) : (pid.charAt(0) === 'b' ? 1 : 0);
      const master = typeof v === 'number' && v >= 0 ? v % 2 === 1 : pid.indexOf('_m') >= 0;
      pieces.push({
        id: pid,
        type: master ? (seat === 0 ? 'red_master' : 'blue_master') : (seat === 0 ? 'red_student' : 'blue_student'),
        board: 'main', position: { cell: String(cell) }, text: master ? 'M' : 'S',
        aria_label: (seat === 0 ? t('red') : t('blue')) + ' ' + (master ? t('master') : t('student')),
        selected: selFrom === cell, actions: []
      });
    }
    // Card panels: Red's two, the neutral card, Blue's two.
    const hands = s.hands || [[], []];
    const slots = [
      { key: 'r0', card: hands[0][0], seat: 0, x: 16 },
      { key: 'r1', card: hands[0][1], seat: 0, x: 128 },
      { key: 'n', card: s.neutral, seat: s.turn, x: 252 },
      { key: 'b0', card: hands[1][0], seat: 1, x: 376 },
      { key: 'b1', card: hands[1][1], seat: 1, x: 488 }
    ];
    labels.push({ id: 'head_red', text: t('red_cards'), x: 16, y: 470, font_size: 14 });
    labels.push({ id: 'head_neutral', text: t('neutral'), x: 252, y: 470, font_size: 14 });
    labels.push({ id: 'head_blue', text: t('blue_cards'), x: 376, y: 470, font_size: 14 });
    for (const slot of slots) {
      if (!slot.card || !CARD_INFO[slot.card]) continue;
      const info = CARD_INFO[slot.card];
      pieces.push({
        id: 'panel_' + slot.key, type: slot.key === 'n' ? 'panel_neutral' : slot.seat === 0 ? 'panel_red' : 'panel_blue',
        board: 'cards', position: { x: slot.x, y: 30 }, text: '', actions: []
      });
      labels.push({ id: 'name_' + slot.key, text: info.name, x: slot.x + 8, y: 498, font_size: 15 });
      // Mini offset diagram, drawn as it acts on the board for its holder:
      // the holder's forward is up for Red and down for Blue.
      const grid = [['·', '·', '·', '·', '·'], ['·', '·', '·', '·', '·'], ['·', '·', '◎', '·', '·'],
        ['·', '·', '·', '·', '·'], ['·', '·', '·', '·', '·']];
      for (const off of info.off) {
        const dr = slot.seat === 0 ? -off[0] : off[0];
        const dc = slot.seat === 0 ? off[1] : -off[1];
        const gr = 2 + dr, gc = 2 + dc;
        if (gr >= 0 && gr < 5 && gc >= 0 && gc < 5) grid[gr][gc] = '●';
      }
      grid.forEach((row, i) => labels.push({
        id: 'grid_' + slot.key + '_' + i, text: row.join(' '),
        x: slot.x + 13, y: 528 + i * 16, font_size: 13
      }));
      labels.push({
        id: 'stamp_' + slot.key,
        text: (info.stamp === 'red' ? t('red') : t('blue')) + ' ●',
        x: slot.x + 8, y: 606, font_size: 11, color: info.stamp === 'red' ? '#e0654f' : '#5b8dd9'
      });
    }
    // Interaction targets and controls, acting viewer only.
    if (active && moves.length) {
      const cardIds = [];
      for (const mv of moves) if (!cardIds.includes(mv.card)) cardIds.push(mv.card);
      for (const cid of cardIds) {
        const slot = slots.find(sl => sl.card === cid && sl.seat === s.turn);
        if (!slot) continue;
        targets.push({
          id: 'card_' + cid, board: 'cards', position: { x: slot.x + 48, y: 110 },
          label: selCard === cid ? '◉' : '◆', aria_label: t('use_card', { card: CARD_INFO[cid].name })
        });
      }
      if (selCard) {
        const froms = [];
        for (const mv of moves) if (mv.card === selCard && !froms.includes(mv.from)) froms.push(mv.from);
        for (const from of froms) targets.push({
          id: 'from_' + from, board: 'main', position: { cell: String(from) },
          label: selFrom === from ? '◉' : '◇',
          aria_label: t('select_piece', { r: Math.floor(from / 5) + 1, c: from % 5 + 1 })
        });
        if (selFrom !== null) for (const mv of moves) {
          if (mv.card !== selCard || mv.from !== selFrom) continue;
          targets.push({
            id: 'to_' + mv.to, board: 'main', position: { cell: String(mv.to) }, label: '●',
            aria_label: t('move_to', { r: Math.floor(mv.to / 5) + 1, c: mv.to % 5 + 1 })
          });
        }
      }
    }
    if (active && passes.length) for (const p of passes)
      controls.push({ id: 'pass_' + p.card, kind: 'button', label: t('pass_card', { card: CARD_INFO[p.card].name }) });
    const scene = { pieces, targets, controls, labels };
    const out = { scene, local_state: { mc: m.move_count, vw: mySeat, card: selCard, from: selFrom } };
    if (makeMove) out.make_move = makeMove;
    return out;
  },
  getLastMoveAnimations(view, scene) {
    // Declared path for the last accepted move, reconstructed only from
    // view.last_move, which the server replaces on every accepted action.
    // A view without the field is an older pinned package: return null to
    // keep the host's position-difference animation. An initial snapshot
    // (null) or a pass card swap explicitly animates nothing ([]).
    if (!view || !Object.prototype.hasOwnProperty.call(view, 'last_move')) return null;
    const move = view.last_move;
    if (!move || move.kind !== 'move' || !move.piece_id || !move.from || !move.to) return [];
    const piece = (scene.pieces || []).find(p => p.id === move.piece_id);
    if (!piece || piece.board !== move.to.board || !piece.position ||
        piece.position.cell !== (move.to.position || {}).cell) return [];
    return [{ piece_id: move.piece_id, duration_ms: 800, path: [move.from, move.to] }];
  }
};
